import java.util.*;

class Solution {
  public int findBottomLeftValue(TreeNode root) {
    // right-to-left BFS: the last node visited is the bottom-left one
    Deque<TreeNode> q = new ArrayDeque<>();
    q.add(root);
    TreeNode node = root;
    while (!q.isEmpty()) {
      node = q.poll();
      if (node.right != null) q.add(node.right);
      if (node.left != null) q.add(node.left);
    }
    return node.val;
  }
}
